def transform(grid):
    """Recolor solid full-width and full-height separator lines to 2."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        if all(value == grid[r][0] for value in grid[r]):
            out[r] = [2] * w
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            for r in range(h):
                out[r][c] = 2
    return out
